import axios from "axios";

export const ApiProfessor = async (professorEndpoint) => {
    try{
        const res = await axios.get("/api/professors/"+professorEndpoint);
        return res.data;
    } catch (e){
        throw e;
    }

};
export const ApiMail = async (userMail) => {
    try{
        const res = await axios.post("/api/email", {userMail});
        return res.data;
    } catch (e) {
        throw e;
    }


};

export default {ApiProfessor};
